// Some portions generated by Codex

const { PNG } = require('pngjs');
const pixelmatchModule = import('pixelmatch');

async function compareImageBuffers(referenceBuffer, actualBuffer) {
    const reference = PNG.sync.read(referenceBuffer);
    const actual = PNG.sync.read(actualBuffer);
    if (reference.width !== actual.width || reference.height !== actual.height) {
        throw new Error(
            `Image dimensions differ: expected ${reference.width}x${reference.height}, got ${actual.width}x${actual.height}`
        );
    }

    const diff = new PNG({ width: actual.width, height: actual.height });
    const { default: pixelmatch } = await pixelmatchModule;
    const differentPixels = pixelmatch(reference.data, actual.data, diff.data, actual.width, actual.height, {
        includeAA: true,
        threshold: 0
    });

    return {
        actualDimensions: { width: actual.width, height: actual.height },
        referenceDimensions: { width: reference.width, height: reference.height },
        diff: PNG.sync.write(diff),
        differentPixels
    };
}

module.exports = { compareImageBuffers };
